import{_ as i,l as r,o as a,c as l,v as t,p as s,x as o,d as p,i as m,S as c}from"./chunks/framework.InCnrqk-.js";const K=JSON.parse('{"title":"Kimi K2","description":"","frontmatter":{"title":"Kimi K2","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kimi-k2.md","filePath":"llm/kimi-k2.md","lastUpdated":1789023840000}'),h={name:"llm/kimi-k2.md"};function E(u,e,d,g,k,A){const n=r("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="kimi-k2" tabindex="-1">Kimi K2 <a class="header-anchor" href="#kimi-k2" aria-label="Permalink to &quot;Kimi K2&quot;">​</a></h1><div class="epigraph"><p>MuonClip 把 Muon 的 token 效率与 QK-Clip 的稳定性接到一起；K2 在 15.5T token 上预训练，全程没有一次 loss spike。</p><footer>—— Kimi Team，Kimi K2: Open Agentic Intelligence，arXiv:2507.20534</footer></div><p><a href="/llm/kimi-k15">k1.5</a> 把推理写成可拉长的 RL 上下文。2025 年 7 月的 <strong>Kimi K2</strong> 换了一条产品轴：<strong>非思考</strong>的万亿 MoE，针对工具使用、软件工程与可行动的智能。结构近 <a href="/llm/deepseek-v2-paper">DeepSeek-V3</a> 式超稀疏 MoE + MLA，但优化器换成 <a href="/llm/muon">Muon</a> 加 QK-Clip。开源 Base 与 Instruct；报告写明当前检查点<strong>不支持视觉</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>高质量人类文本越来越少，「每个 token 学到多少」变成与参数量同级的系数。AdamW 仍是默认，但 Moonlight 已显示同等数据下 Muon 更省 token。把 Muon 拉到万亿 MoE 时，注意力 logits 爆炸比 AdamW 更频繁：soft-cap 只截 softmax 输入，点积本身仍可涨；QK-Norm 又不适配 MLA——推理期键没有完整物化。需要一种<strong>事后缩放投影权重</strong>、而不改当前步前向的稳压。</p><p>后训练的缺口是另一面。自然数据里几乎没有「多步工具、长期计划、可验证交互」。只靠人类示范，agent 上不去；必须合成可检验的工具轨迹，再用可验证奖励与自我评判把开放域也纳入 RL。</p><h3 id="超稀疏-moe-384-选-8-加-1-个共享专家" tabindex="-1">超稀疏 MoE：384 选 8，加 1 个共享专家 <a class="header-anchor" href="#超稀疏-moe-384-选-8-加-1-个共享专家" aria-label="Permalink to &quot;超稀疏 MoE：384 选 8，加 1 个共享专家&quot;">​</a></h3><p>公开规格：总参约 <strong>1.04T</strong>，激活 <strong>32B</strong>；61 层（含 1 层稠密）；注意力隐宽 7168，64 头，<a href="/llm/deepseek-v2-paper">MLA</a>；专家隐宽 2048，<strong>384</strong> 专家、每 token 选 <strong>8</strong>、共享专家 1；<a href="/llm/swiglu">SwiGLU</a>；词表 160K；上下文 <strong>128K</strong>。相对 V3 式设计，报告说按标度律<strong>减少头数</strong>以利长上下文、<strong>提高稀疏度</strong>以提高 token 效率。</p><p><span class="marginnote">32B 激活决定 FLOPs，1T 总量决定装载与专家并行。Tau2-Bench 66.1、ACEBench-En 76.5、SWE-Bench Verified 65.8、SWE-Bench Multilingual 47.3、LiveCodeBench v6 53.7、AIME 2025 49.5、GPQA-Diamond 75.1——均为非思考设置下的报告数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="muonclip-muon-更新之后做-qk-clip" tabindex="-1">MuonClip：Muon 更新之后做 QK-Clip <a class="header-anchor" href="#muonclip-muon-更新之后做-qk-clip" aria-label="Permalink to &quot;MuonClip：Muon 更新之后做 QK-Clip&quot;">​</a></h3><p>Muon 步：动量矩阵经 Newton–Schulz 正交化，再按 \\(\\sqrt{\\max(n,m)}\\cdot 0.2\\) 把更新 RMS 对齐 Adam，然后带 weight decay 的参数更新。QK-Clip 读这一步前向已经算好的每头最大 logit \\(S_{\\max}^h\\)。若超过阈值 \\(\\tau\\)（K2 用 <strong>100</strong>），只缩放该头的投影：MLA 里头专用的 \\(q^C,k^C\\) 乘 \\(\\sqrt{\\gamma}\\)，头专用旋转 \\(q^R\\) 乘 \\(\\gamma\\)，<strong>共享 \\(k^R\\) 不动</strong>以免串头。\\(\\gamma=\\tau/S_{\\max}^h\\)。当前步前向/反向不变，只调节之后的权重范数。中等规模（约 9B 激活 / 53B 总参）上，纯 Muon 的最大 logit 会过 1000；K2 全量训练里 logit 先顶在 100，约 30% 步数后自己落到常规区间，损失曲线无尖峰。</p><p>预训练 <strong>15.5T</strong> 高质量 token，并加合成数据「把已有高质量 token 再挤一遍」。基础设施按训练效率与研究效率一起设计，细节以报告系统节为准。</p>',13)),(a(),s(c,null,{default:o(()=>[m(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%2215.5T%20%2B%20%E5%90%88%E6%88%90%E5%A2%9E%E5%B9%BF%22%5D%20--%3E%20MU%5B%22Muon%EF%BC%9ANewton-Schulz%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20MU%20--%3E%20CLIP%5B%22QK-Clip%EF%BC%9A%E6%8C%89%E5%A4%B4%E7%BC%A9%E6%94%BE%20Wq%2FWk%22%5D%0A%20%20CLIP%20--%3E%20BASE%5B%22K2%20Base%201T%20%2F%2032B%20%E6%BF%80%E6%B4%BB%22%5D%0A%20%20SYN%5B%22%E6%A8%A1%E6%8B%9F%20%2B%20%E7%9C%9F%E5%AE%9E%E7%8E%AF%E5%A2%83%E5%90%88%E6%88%90%E5%B7%A5%E5%85%B7%E8%BD%A8%E8%BF%B9%22%5D%20--%3E%20SFT%5B%22%E5%A4%9A%E9%98%B6%E6%AE%B5%E5%90%8E%E8%AE%AD%E7%BB%83%22%5D%0A%20%20BASE%20--%3E%20SFT%0A%20%20SFT%20--%3E%20RL%5B%22RLVR%20%2B%20%E8%87%AA%E6%88%91%E8%AF%84%E5%88%A4%20rubric%22%5D%0A%20%20RL%20--%3E%20INS%5B%22K2%20Instruct%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h3 id="agent-数据与联合-rl" tabindex="-1">Agent 数据与联合 RL <a class="header-anchor" href="#agent-数据与联合-rl" aria-label="Permalink to &quot;Agent 数据与联合 RL&quot;">​</a></h3><p>后训练多阶段。核心是大规模 <strong>agentic 合成</strong>：在模拟与真实环境里造工具、代理、任务与轨迹，并校验正确性。RL 联合两条奖励：可验证任务上的 RLVR（代码测试、数学等价），以及开放域上的自我评判 rubric——模型学着给自己的输出打分，使对齐从静态偏好集扩到没有外部 checker 的任务。目标是「会调用工具把事做完」，不是把 k1.5 的长思维链再蒸一遍。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Muon 的 token 效率来自对二维权重更新做近正交约束，减少 Adam 在行空间里的冗余步。爆炸 logits 是这条效率的副作用：更新更大，QK 尺度漂得更快。QK-Clip 把稳压放在<strong>权重</strong>而不是激活，因此不破坏 MLA 的推理路径，也不像 soft-cap 那样在已经饱和的点积上切一刀。共享旋转键不剪，是为了不把一个头的过热写进所有头的相位。\\(\\tau=100\\) 在训练后半不再需要调，说明裁剪是过渡护栏，不是永久扭曲几何。</p><p>Agent 合成把「工具使用」从稀有自然演示变成可无限采样的分布。RLVR 保证有 checker 的域（仓库补丁、数学）不会被文风黑客；rubric 自我评判则覆盖没有单一标准答案的助手行为。两者必须联合，否则模型会在 SWE-Bench 上变强、在开放工具对话上只会套模板。</p><p><span class="marginnote">QK-Clip 不是 QK-Norm。Norm 改当前步的 \\(q,k\\)；Clip 改下一步的 \\(W_q,W_k\\)。把 Gemma 3 的 QK-Norm 抄到 K2 的 MLA 实现上，形状会对不上。</span></p><h3 id="和-deepseek-v3、和-k1-5" tabindex="-1">和 DeepSeek-V3、和 k1.5 <a class="header-anchor" href="#和-deepseek-v3、和-k1-5" aria-label="Permalink to &quot;和 DeepSeek-V3、和 k1.5&quot;">​</a></h3><p>架构家族相似：MLA、共享专家、超稀疏路由。差别在优化器（MuonClip vs Adam 系）、头数/稀疏度的标度律选择、以及后训练以 agent 合成为主而不是纯推理长链。k1.5 是思考模型与 128K RL 上下文；K2 Instruct 按非思考评测，SWE-Bench 与 Tau2 才是头条。不要用 k1.5 的 AIME 77.5 去要求 K2 的 49.5——后者不是同一解码制度。LMSYS Arena（报告引用 2025-07-17、三千余票）把 K2 写成当时开源第一、总榜约第五，那是聊天偏好，不是 SWE 主表。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>1T 权重的专家并行、MLA 推理核、160K 词表，都不是「换成 Llama 配置就能服」。无视觉：图要另接系统，不要把 k1.5 的 MathVista 数字接到 K2。15.5T「零尖峰」是这条 MuonClip 跑的结果，不保证换数据混合仍零尖峰。合成轨迹的环境覆盖决定 agent 上限；环境外的工具会表现为自信的错误调用。15.5T 的合成增广是「把已有高质量 token 再挤一遍」，不是凭空多出一套互联网；配比与合成器都不随权重开源，复现的是结构选择而不是损失曲线。rubric 自我评判可能自我强化文风，需要外部红队，不能当成已完成对齐。</p><p>不要编一层层宽之外的隐藏「思考版 K2」写进这篇。Base 与 Instruct 用途不同：续训用 Base，工具调用用 Instruct。许可与再分发以当时模型卡为准。SWE-Bench 多语 47.3 低于英语 Verified 65.8，说明仓库级 agent 仍偏英语轨迹；把英文脚手架直接接到中文仓库会掉点。合成环境若覆盖不到某类 API，模型仍会自信地乱调——这是数据覆盖，不是 MoE 路由能补的。</p><p><span class="marginnote">出处 arXiv:2507.20534；权重见 <code>moonshotai/Kimi-K2-Instruct</code>。Muon 原文与 Moonlight 是优化器前史，不要给 K2 另编一篇只讲 Muon 的会议号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kimi K2 是约 1.04T / 32B 激活的 MLA MoE：384 专家 top-8、1 共享、61 层、128K、无视觉。</li><li>MuonClip = Muon + 按头 QK-Clip；15.5T 预训练宣称零 loss spike。</li><li>后训练以可校验的工具轨迹合成为核心，再联合 RLVR 与自我评判 RL。</li><li>评测主场是非思考设置下的 agent / SWE / 代码 / STEM，不是 k1.5 式长链。</li><li>出处：Kimi Team，<em>Kimi K2: Open Agentic Intelligence</em>，arXiv:2507.20534，2025。</li></ul>',14))])}const M=i(h,[["render",E]]);export{K as __pageData,M as default};
